type TranslationObject = typeof translations.es;

export const languages = Object.keys(translations) as Language[];

export function t(key: keyof TranslationObject, language: Language): string {
  const langObject = translations[language] as TranslationObject;
  return langObject[key] || translations.es[key];
}
